-- ===== 2. 罐区每日巡回检查：计划开始以来（3 ~ 29 天前）的历史任务，有 1 次第二天才补做 =====
INSERT INTO check_task (id, tenant_id, task_no, plan_id, plan_name, template_name, check_type, location, checker_id, checker_name,
                        period_start, due_date, status, items, results, item_count, fail_count, hazard_count, summary, finish_time, version, create_time, update_time)
WITH RECURSIVE seq (n) AS (SELECT 3 UNION ALL SELECT n + 1 FROM seq WHERE n < 29)
SELECT 9700 + n, 1, CONCAT('JC', DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL n DAY), '%Y%m%d'), '-0001'), 9611, '罐区每日巡回检查', t.name, t.check_type,
       '罐区（1#~4# 储罐）', 103, '李四（作业负责人）', DATE_SUB(CURDATE(), INTERVAL n DAY), DATE_SUB(CURDATE(), INTERVAL n DAY), 'DONE', t.items,
       '[{"content":"储罐液位、压力、温度在正常范围","standard":"对照 DCS 显示和现场仪表，偏差不超过 5%","category":"设备设施","ok":true,"note":null},{"content":"罐体、管线、阀门无跑冒滴漏","standard":"目视检查，法兰、阀门填料处无渗漏痕迹","category":"设备设施","ok":true,"note":null},{"content":"可燃气体报警器工作正常","standard":"指示灯正常，无故障报警","category":"设备设施","ok":true,"note":null},{"content":"防火堤完好，排水阀处于关闭状态","standard":"堤内无积水、无杂物，雨排阀关闭并挂牌","category":"作业环境","ok":true,"note":null},{"content":"静电接地、防雷设施完好","standard":"接地线连接牢固，无锈蚀断裂","category":"设备设施","ok":true,"note":null},{"content":"消防器材齐全有效","standard":"灭火器压力在绿区，消防栓无遮挡","category":"设备设施","ok":true,"note":null},{"content":"罐区内无动火、无违规使用手机等火源","standard":"进入罐区人员已交出火种，有动火作业的持有效作业票","category":"人员行为","ok":true,"note":null},{"content":"巡检记录、交接班记录填写完整","standard":"上一班记录完整、签名齐全","category":"安全管理","ok":true,"note":null}]', 8, 0, 0, IF(n = 17, '前一天交接班遗漏，次日补做，检查正常', '检查正常'),
       IF(n = 17, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL n - 1 DAY), '09:20:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL n DAY), '10:00:00')),
       1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL n DAY), '00:05:00'), NOW()
FROM seq JOIN check_template t ON t.id = 9601
-- 跳过已经有任务的日期（定时任务每天会生成当天的任务）
WHERE NOT EXISTS (SELECT 1 FROM check_task x WHERE x.plan_id = 9611 AND x.period_start = DATE_SUB(CURDATE(), INTERVAL seq.n DAY) AND x.deleted = 0);

-- ===== 3. 班前会：两个班组成立得更早，补上之前几个月的记录（偶尔漏开），最近一个月开展率下滑 =====
-- 跳过已经有记录的日期；点名记录只给这里新加的班前会补
INSERT INTO shift_meeting (id, tenant_id, team_id, team_name, meeting_date, shift, host_id, host_name, topics, ai_used,
                           member_count, present_count, unfit_count, create_time, update_time)
WITH RECURSIVE seq (n) AS (SELECT 30 UNION ALL SELECT n + 1 FROM seq WHERE n < 150)
SELECT 96200 + n, 1, 9601, '罐区操作班', DATE_SUB(CURDATE(), INTERVAL n DAY), 'DAY', 103, '李四（作业负责人）',
       '1. 罐区今天正常收发料，装卸车前检查静电接地夹\n2. 巡检储罐液位、呼吸阀，发现泄漏立即报告\n3. 进入罐区禁止携带火种和非防爆手机\n4. 正确佩戴防毒半面罩和防静电工作服',
       IF(n % 4 = 0, 1, 0), 2, 2, 0, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL n DAY), '07:50:00'), NOW()
FROM seq WHERE n % 17 <> 0
  AND NOT EXISTS (SELECT 1 FROM shift_meeting x WHERE x.team_id = 9601 AND x.meeting_date = DATE_SUB(CURDATE(), INTERVAL seq.n DAY) AND x.deleted = 0);

INSERT INTO shift_meeting (id, tenant_id, team_id, team_name, meeting_date, shift, host_id, host_name, topics, ai_used,
                           member_count, present_count, unfit_count, create_time, update_time)
WITH RECURSIVE seq (n) AS (SELECT 10 UNION ALL SELECT n + 1 FROM seq WHERE n < 90)
SELECT 96400 + n, 1, 9602, '安全管理组', DATE_SUB(CURDATE(), INTERVAL n DAY), 'DAY', 102, '张三（安全员）',
       '1. 检查今天的作业票气体检测和监护人到位情况\n2. 跟踪逾期隐患整改进度\n3. 承包商作业必须持证上岗',
       0, 2, 2, 0, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL n DAY), '08:10:00'), NOW()
FROM seq WHERE n % 9 <> 0
  AND NOT EXISTS (SELECT 1 FROM shift_meeting x WHERE x.team_id = 9602 AND x.meeting_date = DATE_SUB(CURDATE(), INTERVAL seq.n DAY) AND x.deleted = 0);

