WITH RECURSIVE seq (n) AS (SELECT 30 UNION ALL SELECT n + 1 FROM seq WHERE n < 150)
SELECT 98000 + n * 2, 1, 96200 + n, 103, '李四（作业负责人）', 'PRESENT', 'GOOD', NULL,
       TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL n DAY), '07:55:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL n DAY), '07:55:00'), NOW()
